def quote_env(v):
    # keep URL unquoted; quote only if needed
    if re.search(r'\s|#|"|\'', v):
        return '"' + v.replace('\\','\\\\').replace('"','\\"') + '"'
    return v

def upsert_env(path: Path):
    path.parent.mkdir(parents=True, exist_ok=True)
    lines = path.read_text().splitlines() if path.exists() else []
    seen = set()
    out = []
    for line in lines:
        m = re.match(r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=.*$', line)
        if m and m.group(1) in updates:
            key = m.group(1)
            out.append(f'{key}={quote_env(updates[key])}')
            seen.add(key)
        else:
            out.append(line)
    if out and out[-1].strip():
        out.append('')
    for key, val in updates.items():
        if key not in seen:
            out.append(f'{key}={quote_env(val)}')
    path.write_text('\n'.join(out) + '\n')
    try:
        path.chmod(0o600)
    except PermissionError:
        pass

for t in targets:
    upsert_env(t)
print('Updated env files:')
for t in targets:
    print(f'- {t}')
print('Added/updated variables: ' + ', '.join(updates.keys()))"}

